using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2. TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {found!.Type.Name}");
}

// Now demonstrate the "not available" branch using a source-gen context
// that only knows about Person, so int[] is unresolved.
var strictOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonContext()
};

if (strictOptions.TryGetTypeInfo<int[]>(out _))
{
    Console.WriteLine("int[] metadata found (unexpected)");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int[]> returned false — no metadata, no exception");
}

public record Person(string Name, int Age);

